import React from "react";
import { Bar } from "react-chartjs-2";
import {
  Chart as ChartJS,
  BarElement,
  CategoryScale,
  LinearScale
} from "chart.js";

ChartJS.register(BarElement, CategoryScale, LinearScale);

function Dashboard() {
  // SAMPLE DATA (replace later with real backend data)
  const chartData = {
    labels: ["Low", "Average", "High"],
    datasets: [
      {
        label: "Student Performance Distribution",
        data: [10, 25, 15]
      }
    ]
  };

  // SAMPLE TABLE DATA
  const sampleData = [
    { hs_avg: 85, gpa: 3.2, math: 40, result: "High" },
    { hs_avg: 70, gpa: 2.5, math: 30, result: "Average" },
    { hs_avg: 60, gpa: 1.8, math: 25, result: "Low" }
  ];

  return (
    <div className="dashboard">
      <h2>📊 Data Insights</h2>

      {/* CHART */}
      <div className="chart">
        <Bar data={chartData} />
      </div>

      {/* TABLE */}
      <h3>📋 Sample Cleaned Data</h3>
      <table>
        <thead>
          <tr>
            <th>HS Avg</th>
            <th>GPA</th>
            <th>Math</th>
            <th>Performance</th>
          </tr>
        </thead>
        <tbody>
          {sampleData.map((row, index) => (
            <tr key={index}>
              <td>{row.hs_avg}</td>
              <td>{row.gpa}</td>
              <td>{row.math}</td>
              <td>{row.result}</td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* INSIGHTS */}
      <div className="insights">
        <h3>🧠 Student Insights</h3>
        <p>
          • Students with GPA above 3.0 are more likely to achieve high performance.
        </p>
        <p>
          • Lower math scores often correlate with lower GPA outcomes.
        </p>
        <p>
          • High school average is a strong predictor of academic success.
        </p>
      </div>
    </div>
  );
}

export default Dashboard;
